public class LocalTranslationPage:UserControl {
 readonly Func<Profile> selected;readonly Action<string> notify;readonly ListBox list=new ListBox();readonly SleekCard detail=new SleekCard();readonly Label title,modelLine,runTitle,state,counts,scope,explanation,empty;readonly SleekButton create,manage,start,remove,folder,details,editor,retry;readonly CheckBox use=new CheckBox();readonly Label eta=new Label();readonly SleekProgress progress=new SleekProgress();readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();
 Color background=Color.FromArgb(15,17,25),card=Color.FromArgb(27,30,42),paper=Color.White,muted=Color.Silver,accent=Color.FromArgb(100,125,245);bool updating,working;string listStamp="",lastGame="";
