  list.BorderStyle=BorderStyle.None;list.IntegralHeight=false;list.DrawMode=DrawMode.OwnerDrawFixed;list.ItemHeight=67;list.DrawItem+=DrawRun;list.SelectedIndexChanged+=delegate{RefreshDetail();};Controls.Add(list);
  detail.BackColor=card;Controls.Add(detail);runTitle=new Label{Font=new Font("Segoe UI",16,FontStyle.Bold)};state=new Label{Font=new Font("Segoe UI",11,FontStyle.Bold)};counts=new Label();scope=new Label();explanation=new Label();
