 public void Theme(Color bg,Color panel,Color text,Color secondary,Color color){background=bg;card=panel;paper=text;muted=secondary;accent=color;BackColor=bg;ForeColor=text;detail.BackColor=panel;list.BackColor=panel;list.ForeColor=text;foreach(Control c in Controls){c.ForeColor=text;var b=c as SleekButton;if(b!=null)b.BackColor=b.Primary?color:panel;}foreach(Control c in detail.Controls){c.ForeColor=c==scope||c==explanation?secondary:text;c.BackColor=panel;var b=c as SleekButton;if(b!=null)b.BackColor=b.Primary?color:panel;}modelLine.ForeColor=secondary;empty.ForeColor=secondary;progress.BackColor=bg;progress.ForeColor=color;list.Invalidate();}
 void Arrange(){
  int w=Width,h=Height,pad=16,left=w<640?170:208;title.SetBounds(0,0,Math.Max(220,w-155),42);manage.SetBounds(w-145,5,145,38);modelLine.SetBounds(0,48,w,32);create.SetBounds(0,87,left,40);folder.SetBounds(w-145,87,145,40);details.SetBounds(left+14,87,Math.Min(110,Math.Max(70,w-left-175)),40);list.SetBounds(0,140,left,Math.Max(180,h-148));detail.SetBounds(left+14,140,Math.Max(230,w-left-14),Math.Max(280,h-148));
  int d=detail.Width;bool compact=detail.Height<420;runTitle.SetBounds(pad,10,d-pad*2,compact?28:42);state.SetBounds(pad,compact?42:64,d-pad*2,24);progress.SetBounds(pad,compact?76:100,d-pad*2,7);counts.SetBounds(pad,compact?92:118,d-pad*2,40);eta.SetBounds(pad,compact?136:166,d-pad*2,compact?28:36);scope.Visible=!compact;scope.SetBounds(pad,compact?174:215,d-pad*2,compact?24:64);
  int actions=Math.Max(compact?170:295,detail.Height-122),bw=(d-pad*2-10)/2;start.SetBounds(pad,actions,bw,32);editor.SetBounds(start.Right+10,actions,bw,32);retry.SetBounds(pad,actions+38,bw,32);remove.SetBounds(retry.Right+10,retry.Top,bw,32);use.SetBounds(pad,actions+77,d-pad*2,30);explanation.Visible=false;empty.SetBounds(0,175,w,110);

 }
 void DrawRun(object sender,DrawItemEventArgs e){if(e.Index<0)return;var run=list.Items[e.Index] as LocalRun;if(run==null)return;bool active=(e.State&DrawItemState.Selected)!=0;using(var brush=new SolidBrush(active?LauncherPaint.Blend(card,accent,.22):card))e.Graphics.FillRectangle(brush,e.Bounds);var r=e.Bounds;r.Inflate(-12,-6);using(var bold=new Font(Font,FontStyle.Bold))TextRenderer.DrawText(e.Graphics,run.Name,bold,new Rectangle(r.X,r.Y,r.Width,24),paper,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);TextRenderer.DrawText(e.Graphics,run.State+" · "+run.Done.ToString("N0")+" / "+run.Total.ToString("N0"),Font,new Rectangle(r.X,r.Y+28,r.Width,22),muted,TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine);}
 public void RefreshState(){try{RefreshCore();}catch(IOException e){state.Text="Status temporarily unavailable";eta.Text=e.Message;notify("Local translation status: "+e.Message);}catch(ArgumentException e){state.Text="Status file needs attention";eta.Text=e.Message;notify(e.Message);}}
 void RefreshCore(){
  var p=selected();string game=p==null?"":LocalTranslation.GameKey(p.Root),id=Current==null?null:Current.Id;var rows=p==null?new List<LocalRun>():LocalTranslation.Runs(p.Root);string stamp=game+string.Join("|",rows.Select(x=>x.Id+x.State+x.Done+x.Total+x.Failed));
  if(stamp!=listStamp){updating=true;try{list.Items.Clear();list.Items.AddRange(rows.Cast<object>().ToArray());list.SelectedItem=rows.FirstOrDefault(x=>x.Id==id)??rows.FirstOrDefault();}finally{updating=false;}listStamp=stamp;}
  lastGame=game;create.Enabled=p!=null&&!working;modelLine.Text=string.Join("   ·   ",LocalTranslation.Models.Select(x=>x.Id+": "+(LocalTranslation.ModelInstalled(x.Id)?"installed":LocalTranslation.InstallStatus(x.Id).State??"not installed")));RefreshDetail();
 }
 void RefreshDetail(){
  var run=Current;bool present=run!=null;detail.Visible=present;details.Visible=present;empty.Visible=!present;list.Visible=selected()!=null;empty.Text=selected()==null?"Choose an installed game from your library.\r\nLocal translation does not require a curated English pack.":"No local runs yet.\r\nInstall a model, then choose a language and text categories.";if(!present)return;
  runTitle.Text=run.Name;state.Text=run.State+(run.State=="Running"&&run.Seconds>0?" · "+(Math.Max(0,run.Done-run.Reused)*60/run.Seconds).ToString("0.0")+" entries/min":"");progress.Value=run.Total==0?0:Math.Min(100,(int)(100L*run.Done/Math.Max(1,run.Total)));counts.Text=run.Done.ToString("N0")+" completed / "+run.Total.ToString("N0")+" selected\r\n"+run.Failed.ToString("N0")+" failed · "+run.Deferred.ToString("N0")+" deferred · "+run.Excluded.ToString("N0")+" excluded";
  var options=LocalTranslation.Options(run);double rate=run.RecentRate;int remaining=Math.Max(0,run.Total-run.Done-run.Failed-run.Deferred);eta.Text=(run.Total>0?(100L*(run.Done+run.Failed+run.Deferred)/run.Total)+"% · ":"")+(remaining==0?"Selected queue finished":rate>0?"~"+TimeSpan.FromMinutes(remaining/rate).ToString(@"d\d\ h\h\ m\m")+" remaining":"Estimating remaining time…")+"\r\n"+options.Backend.ToUpperInvariant()+(string.IsNullOrEmpty(options.Device)?" · automatic device":" · "+options.Device);
  scope.AutoEllipsis=true;scope.Text=LocalLanguages.All[run.Language]+" · PLaMo "+run.Model+"\r\n"+string.Join(", ",options.Scope)+"\r\n"+(string.IsNullOrEmpty(run.Error)?"Uncached and excluded text stays original.":run.Error);
  bool running=new[]{"Running","Starting model","Indexing"}.Contains(run.State)&&LocalTranslation.Requested(run.Id)=="run";start.Text=running?"Pause":"Resume pending";start.Enabled=remove.Enabled=editor.Enabled=details.Enabled=!working;retry.Enabled=!working&&run.Failed>0&&!running;
  updating=true;try{var b=LocalTranslation.Binding(run.Root);use.Checked=b.Enabled&&b.RunId==run.Id;use.Enabled=!working;}finally{updating=false;}
  explanation.Text="Cached text works while paused. Switch local runs live; changing English/local mode takes effect on the next game launch.";
 }
  void ShowDetails(){var r=Current;if(r==null)return;var census=LocalTranslation.Read<Dictionary<string,object>>(LocalTranslation.RunFile(r.Id,"index-status.json"));object unreadable;census.TryGetValue("unreadableFiles",out unreadable);double rate=r.Seconds>0?Math.Max(0,r.Done-r.Reused)*60/r.Seconds:0;string speed=rate>0?"Observed: "+rate.ToString("0.0")+" entries/min · estimated remaining "+TimeSpan.FromMinutes(Math.Max(0,r.Total-r.Done-r.Failed)/rate).ToString(@"d\d\ h\h\ m\m"):"Speed estimate becomes available after processing text.";MessageBox.Show(FindForm(),r.Name+"\r\n"+LocalLanguages.All[r.Language]+" · PLaMo "+r.Model+"\r\n"+string.Join(", ",r.Scope)+"\r\n\r\n"+speed+"\r\n"+(string.IsNullOrEmpty(r.Error)?"No reported processing errors.":r.Error)+"\r\nUnreadable data files: "+(unreadable==null?"not indexed yet":LocalTranslation.Json.Serialize(unreadable))+"\r\n\r\nCached text works while paused. Switching English/local mode takes effect on the next game launch. Text embedded in images is not translated.","Local run details",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 async Task Action(System.Action action){if(working)return;working=true;RefreshDetail();try{await Task.Run(action);notify("Local translation updated · English packs and saves preserved");}catch(Exception e){Error(e);}finally{working=false;listStamp="";RefreshState();}}
 void Error(Exception e){notify(e.Message);MessageBox.Show(FindForm(),e.Message,"Local translation",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 void NewRun(){var p=selected();if(p==null)return;using(var d=new LocalRunDialog(p,background,card,paper,accent))if(d.ShowDialog(FindForm())==DialogResult.OK){try{LocalTranslation.Create(p,d.RunName,d.ModelId,d.Language,d.Scope);listStamp="";RefreshState();}catch(Exception e){Error(e);}}}
}
public class LocalRunDialog:Form {
 TextBox name=new TextBox();ComboBox model=new ComboBox(),language=new ComboBox();CheckedListBox scope=new CheckedListBox();public string RunName{get{return name.Text;}}public string ModelId{get{return ((LocalModel)model.SelectedItem).Id;}}public string Language{get{return ((KeyValuePair<string,string>)language.SelectedItem).Key;}}public string[] Scope{get{return scope.CheckedItems.Cast<string>().ToArray();}}
 public LocalRunDialog(Profile p,Color bg,Color card,Color text,Color accent){Text="New local translation run";ClientSize=new Size(520,480);MinimumSize=new Size(500,500);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;
  var heading=new Label{Text="Choose what to translate",Font=new Font(Font.FontFamily,18,FontStyle.Bold),Location=new Point(24,20),Size=new Size(470,38)};Controls.Add(heading);
  Controls.Add(new Label{Text="Run name (optional)",Location=new Point(24,75),Size=new Size(470,23)});name.SetBounds(24,101,470,28);Controls.Add(name);
  model.DropDownStyle=ComboBoxStyle.DropDownList;model.Items.AddRange(LocalTranslation.Models);model.SelectedIndex=0;model.SetBounds(24,151,470,30);Controls.Add(model);
  language.DropDownStyle=ComboBoxStyle.DropDownList;language.DisplayMember="Value";language.Items.AddRange(LocalLanguages.All.OrderBy(x=>x.Value).Cast<object>().ToArray());language.SelectedItem=LocalLanguages.All.Single(x=>x.Key=="en");language.SetBounds(24,200,470,30);Controls.Add(language);
