  Controls.Add(new Label{Text="Unchecked categories stay original. Names are optional.\r\nA run can be used before every entry is translated.",Location=new Point(24,382),Size=new Size(470,42)});
  var create=new SleekButton{Text="Create run",Primary=true,BackColor=accent,ForeColor=text,Location=new Point(330,434),Size=new Size(164,36)};create.Click+=delegate{if(Scope.Length==0){MessageBox.Show(this,"Select at least one category.");return;}DialogResult=DialogResult.OK;};Controls.Add(create);AcceptButton=create;
 }
