public class LocalModelsDialog:Form {
 readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer();CancellationTokenSource cancellation;bool busy;Label[] states=new Label[2];SleekProgress[] bars=new SleekProgress[2];SleekButton[] installs=new SleekButton[2],removes=new SleekButton[2];ComboBox backend=new ComboBox();Label detail;
 public LocalModelsDialog(Color bg,Color card,Color text,Color muted,Color accent){Text="Local translation models";ClientSize=new Size(620,480);MinimumSize=new Size(620,480);StartPosition=FormStartPosition.CenterParent;BackColor=bg;ForeColor=text;Font=new Font("Segoe UI",10);FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;
  Controls.Add(new Label{Text="Models on this PC",Font=new Font(Font.FontFamily,20,FontStyle.Bold),Location=new Point(24,20),Size=new Size(560,40)});
  Controls.Add(new Label{Text="Downloaded from PFN · translations run locally · no API key",ForeColor=muted,Location=new Point(24,65),Size=new Size(560,24)});
  backend.DropDownStyle=ComboBoxStyle.DropDownList;backend.Items.AddRange(new object[]{"CPU · broad compatibility","Vulkan GPU · compatible graphics card required"});backend.SelectedIndex=0;backend.SetBounds(24,99,572,30);Controls.Add(backend);
  for(int i=0;i<2;i++){int index=i;var m=LocalTranslation.Models[i];int top=150+i*123;var panel=new SleekCard{BackColor=card,Location=new Point(24,top),Size=new Size(572,112)};Controls.Add(panel);panel.Controls.Add(new Label{Text=m.Label,Font=new Font(Font,FontStyle.Bold),Location=new Point(16,13),Size=new Size(370,24)});states[i]=new Label{ForeColor=muted,Location=new Point(16,45),Size=new Size(365,24)};panel.Controls.Add(states[i]);bars[i]=new SleekProgress{Maximum=100,ForeColor=accent,BackColor=card,Location=new Point(16,79),Size=new Size(365,5)};panel.Controls.Add(bars[i]);installs[i]=new SleekButton{Text="Install / repair",Primary=true,BackColor=accent,ForeColor=text,Location=new Point(395,10),Size=new Size(160,38)};installs[i].Click+=async delegate{await Install(index);};panel.Controls.Add(installs[i]);removes[i]=new SleekButton{Text="Remove model",BackColor=card,ForeColor=text,Location=new Point(395,58),Size=new Size(160,36)};removes[i].Click+=async delegate{if(busy)return;if(MessageBox.Show(this,"Remove only PLaMo "+m.Id+"? Dependent runs will pause; cached translations are kept.","Remove model",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;busy=true;try{await Task.Run(()=>LocalTranslation.Uninstall(m.Id));}catch(Exception e){MessageBox.Show(this,e.Message);}finally{busy=false;RefreshStatus();}};panel.Controls.Add(removes[i]);}
  detail=new Label{ForeColor=muted,Location=new Point(24,405),Size=new Size(572,35),Text="Removing a model keeps your generated translation caches."};Controls.Add(detail);
  var source=new LinkLabel{Text="Model sources and PLaMo Community License",Location=new Point(24,448),Size=new Size(420,24),LinkColor=accent};source.LinkClicked+=delegate{System.Diagnostics.Process.Start("https://huggingface.co/pfnet/plamo-3-translate-0.8b-GGUF");};Controls.Add(source);var stop=new SleekButton{Text="Pause download",Location=new Point(441,443),Size=new Size(155,30),BackColor=card,ForeColor=text};stop.Click+=delegate{if(cancellation!=null)cancellation.Cancel();};Controls.Add(stop);
  timer.Interval=500;timer.Tick+=delegate{RefreshStatus();};timer.Start();FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy){e.Cancel=true;detail.Text="Pause the download or wait for the current model operation to finish.";}};FormClosed+=delegate{timer.Stop();timer.Dispose();};RefreshStatus();
 }
 async Task Install(int index){if(busy)return;busy=true;cancellation=new CancellationTokenSource();bool gpu=backend.SelectedIndex==1;try{await Task.Run(()=>LocalTranslation.Install(LocalTranslation.Models[index].Id,gpu,cancellation.Token));}catch(OperationCanceledException){detail.Text="Download paused. Install / repair resumes it.";}catch(Exception e){MessageBox.Show(this,e.Message,"Model setup",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{busy=false;cancellation.Dispose();cancellation=null;RefreshStatus();}}
 void RefreshStatus(){for(int i=0;i<2;i++){var m=LocalTranslation.Models[i];var s=LocalTranslation.InstallStatus(m.Id);states[i].Text=s.State??(LocalTranslation.ModelInstalled(m.Id)?"Installed":"Not installed");if(s.Total>0&&s.State=="Downloading")states[i].Text+=" · "+(s.Received/1000000)+" / "+(s.Total/1000000)+" MB";bars[i].Value=s.Total>0?Math.Min(100,(int)(s.Received*100/s.Total)):LocalTranslation.ModelInstalled(m.Id)?100:0;installs[i].Enabled=removes[i].Enabled=!busy;removes[i].Visible=Directory.Exists(m.Folder);}backend.Enabled=!busy;}
}
